def fizzbuzz(n: int) -> list[str]:
    """
    For numbers 1 to n, 'Fizz' if divisible by 3, 'Buzz' if divisible by 5,
    'FizzBuzz' if both, else the number as a string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result
